    MIN_CLIENT: MIN_CLIENT,
    tool: tool,
    has: hasMethods,
    ready: ready,
    call: call,
    version: version,
    versionText: versionText,
    errCode: errCode,
    toTempPath: toTempPath,
    storage: storage,
    vibrate: vibrate,
