    fg.addColorStop(0, 'rgba(255,255,255,.98)');
    fg.addColorStop(0.3, fadeA(col, 0.95));
    fg.addColorStop(0.75, fadeA(col, 0.55));
    fg.addColorStop(1, fadeA(col, 0));
    ctx.fillStyle = fg;
    ctx.beginPath();
    ctx.moveTo(0, -L);
    ctx.bezierCurveTo(r * 1.5, -L * 0.45, r * 1.25, r * 0.6, 0, r * 1.8);
