    var tip = { x: 0, y: -L }, rT = { x: Wd, y: -L * 0.3 }, rB = { x: Wd * 0.7, y: L * 0.38 }, bot = { x: 0, y: L * 0.95 };
    var lT = { x: -Wd, y: -L * 0.3 }, lB = { x: -Wd * 0.7, y: L * 0.38 }, mid = { x: Wd * 0.12, y: -L * 0.1 };
