      var tx = Math.cos(a0 + 0.42 * (Math.PI * 2 / teeth)) * R, ty = Math.sin(a0 + 0.42 * (Math.PI * 2 / teeth)) * R;
      if (k === 0) ctx.moveTo(vx, vy); else ctx.lineTo(vx, vy);
