        ctx.beginPath(); ctx.arc(p.x, p.y, R + 8, 0, Math.PI * 2); ctx.fill();
        ctx.shadowColor = rc;
        ctx.shadowBlur = 12;
        ctx.strokeStyle = rc;
        ctx.globalAlpha = 0.75;
