        body.addColorStop(0, 'rgba(79,214,232,.75)');
        body.addColorStop(0.25, 'rgba(32,150,210,.6)');
        body.addColorStop(1, 'rgba(12,60,130,.35)');
        wavePath(-12, 14, tGlobal * 5);
        ctx.fillStyle = 'rgba(20,90,170,.45)';
        ctx.fill();
        wavePath(0, 10, tGlobal * 7 + 1.3);
        ctx.fillStyle = body;
        ctx.fill();
